import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Events Data Model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number; // Default to 0 for nullable values
}

// Create ingestion pipeline for user activity events
// Optimized for queries:
// 1. Activity counts per user over a date range -> user_id, event_ts ordering
// 2. Total duration per action type -> can use action in WHERE clauses efficiently
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "event_ts"]
  },
  stream: true,
  ingestApi: true,
});
